action.code:
float tmin = min_t;
float tmax = max_t;

for (int i = 0; i < 3; ++i) {
    float invD;
    float origin;
    float b0, b1;

    if (i == 0) {
        invD   = ray_inv_dir.x;
        origin = ray_org.x;
        b0     = bmin[0];
        b1     = bmax[0];
    } else if (i == 1) {
        invD   = ray_inv_dir.y;
        origin = ray_org.y;
        b0     = bmin[1];
        b1     = bmax[1];
    } else {
        invD   = ray_inv_dir.z;
        origin = ray_org.z;
        b0     = bmin[2];
        b1     = bmax[2];
    }

    if (invD == 0.0f) {
        if (origin < b0 || origin > b1) {
            return false;
        }
        continue;
    }

    float t0 = (b0 - origin) * invD;
    float t1 = (b1 - origin) * invD;

    if (ray_dir_sign[i]) {
        std::swap(t0, t1);
    }

    tmin = std::max(tmin, t0);
    tmax = std::min(tmax, t1);

    if (tmax < tmin) {
        return false;
    }
}

*tminOut = tmin;
*tmaxOut = tmax;
return true;

